//
// UMI-tools dedup, index BAM file and run samtools stats, flagstat and idxstats
//

include { UMITOOLS_DEDUP                           } from 'nf-core/umitools/dedup'
include { SAMTOOLS_INDEX                           } from 'nf-core/samtools/index'
include { SAMTOOLS_VIEW as SAMTOOLS_VIEW_PRIMARY   } from 'nf-core/samtools/view'
include { SAMTOOLS_INDEX as SAMTOOLS_INDEX_PRIMARY } from 'nf-core/samtools/index'
include { BAM_STATS_SAMTOOLS                       } from 'nf-core/bam_stats_samtools'

workflow BAM_DEDUP_STATS_SAMTOOLS_UMITOOLS {
    take:
    ch_bam_bai // channel: [ val(meta), path(bam), path(bai/csi) ]
    val_get_dedup_stats // boolean: true/false
    val_primary_only // boolean: true/false

    main:

    //
    // Optionally filter to primary alignments before deduplication
    //
    if (val_primary_only) {
        SAMTOOLS_VIEW_PRIMARY(
            ch_bam_bai,
            [[], [], []],
            [[], []],
            [[], []],
            [],
        )

        SAMTOOLS_INDEX_PRIMARY(SAMTOOLS_VIEW_PRIMARY.out.bam)

        ch_dedup_input = SAMTOOLS_VIEW_PRIMARY.out.bam.join(SAMTOOLS_INDEX_PRIMARY.out.index, by: [0])
    }
    else {
        ch_dedup_input = ch_bam_bai
    }

    //
    // UMI-tools dedup
    //
    UMITOOLS_DEDUP(ch_dedup_input, val_get_dedup_stats)

    //
    // Index BAM file and run samtools stats, flagstat and idxstats
    //
    SAMTOOLS_INDEX(UMITOOLS_DEDUP.out.bam)

    ch_bam_bai_dedup = UMITOOLS_DEDUP.out.bam.join(SAMTOOLS_INDEX.out.index, by: [0])

    BAM_STATS_SAMTOOLS(ch_bam_bai_dedup, [[:], [], []])

    emit:
    bam                  = UMITOOLS_DEDUP.out.bam // channel: [ val(meta), path(bam) ]
    deduplog             = UMITOOLS_DEDUP.out.log // channel: [ val(meta), path(log) ]
    tsv_edit_distance    = UMITOOLS_DEDUP.out.tsv_edit_distance // channel: [ val(meta), path(tsv) ]
    tsv_per_umi          = UMITOOLS_DEDUP.out.tsv_per_umi // channel: [ val(meta), path(tsv) ]
    tsv_umi_per_position = UMITOOLS_DEDUP.out.tsv_umi_per_position // channel: [ val(meta), path(tsv) ]
    index                = SAMTOOLS_INDEX.out.index // channel: [ val(meta), path(index) ]
    stats                = BAM_STATS_SAMTOOLS.out.stats // channel: [ val(meta), path(stats) ]
    flagstat             = BAM_STATS_SAMTOOLS.out.flagstat // channel: [ val(meta), path(flagstat) ]
    idxstats             = BAM_STATS_SAMTOOLS.out.idxstats // channel: [ val(meta), path(idxstats) ]
}

nextflow_workflow {

    name "Test Workflow BAM_DEDUP_STATS_SAMTOOLS_UMITOOLS"
    script "../main.nf"
    workflow "BAM_DEDUP_STATS_SAMTOOLS_UMITOOLS"
    config "./nextflow.config"
    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/bam_dedup_stats_samtools_umitools"
    tag "subworkflows/bam_stats_samtools"
    tag "bam_dedup_stats_samtools_umitools"
    tag "bam_stats_samtools"
    tag "samtools"
    tag "samtools/index"
    tag "samtools/view"
    tag "samtools/stats"
    tag "samtools/idxstats"
    tag "samtools/flagstat"
    tag "umitools"
    tag "umitools/dedup"

    test("sarscov2_bam_bai") {

        when {
            workflow {
                """
                val_get_dedup_stats = false

                input[0] = Channel.of([
                    [ id:'test'], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.umi.sorted.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.umi.sorted.bam.bai', checkIfExists: true)
                ])
                input[1] = val_get_dedup_stats
                input[2] = false
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success},
                { assert snapshot(sanitizeOutput(workflow.out, readsMD5Keys:["bam"], unstableKeys: ["index", "deduplog"])).match() },
            )
        }
    }

    test("sarscov2_bam_bai - primary_only") {

        when {
            workflow {
                """
                val_get_dedup_stats = false

                input[0] = Channel.of([
                    [ id:'test'], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.umi.sorted.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.umi.sorted.bam.bai', checkIfExists: true)
                ])
                input[1] = val_get_dedup_stats
                input[2] = true
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success},
                { assert snapshot(sanitizeOutput(workflow.out, readsMD5Keys:["bam"], unstableKeys: ["index", "deduplog"])).match() },
            )
        }
    }

    test("sarscov2_bam_bai - stub") {

        options "-stub"

        when {
            workflow {
                """
                val_get_dedup_stats = false

                input[0] = Channel.of([
                    [ id:'test'], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.umi.sorted.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.umi.sorted.bam.bai', checkIfExists: true)
                ])
                input[1] = val_get_dedup_stats
                input[2] = false
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success},
                { assert snapshot(workflow.out).match() }
            )
        }
    }
}
